// Normalises the three entry points. The schedule always delivers. A manual
// run or a call from another workflow is a dry run unless it passes
// dry_run: false. Optional inputs: use_llm (default true) and date
// (YYYY-MM-DD, replaces today's Europe/Athens date for testing).
const input = $input.first()?.json ?? {};
const scheduled = Object.prototype.hasOwnProperty.call(input, 'timestamp')
  || Object.prototype.hasOwnProperty.call(input, 'Readable date');
const zone = 'Europe/Athens';
let now = DateTime.now().setZone(zone);
if (!scheduled && typeof input.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(input.date)) {
  now = DateTime.fromISO(input.date, { zone }).set({ hour: now.hour, minute: now.minute, second: now.second });
}
return [{
  json: {
    job: "morning-digest",
    scheduled,
    dry_run: scheduled ? false : input.dry_run !== false,
    use_llm: scheduled ? true : input.use_llm !== false,
    now: now.toISO(),
    today: now.toISODate(),
    yesterday: now.minus({ days: 1 }).toISODate(),
    month_start: now.startOf('month').toISODate(),
    weekday: now.setLocale('en').toFormat('cccc'),
  },
}];

// The Nextcloud MCP server is stateful: later calls carry the session id
// returned by initialize.
const res = $input.first().json;
const headers = res.headers || {};
const sid = headers['mcp-session-id'] || headers['Mcp-Session-Id'];
if (!sid) throw new Error(`Nextcloud MCP: initialize returned no session id (HTTP ${res.statusCode ?? '?'})`);
return [{ json: { sid } }];

const MAX_MESSAGE = 3500;

function decodeEntities(text) {
  return String(text ?? '')
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&');
}

function oneLine(text, max) {
  let s = String(text ?? '').replace(/\s+/g, ' ').trim();
  if (max && s.length > max) s = `${s.slice(0, max - 1).replace(/\s+\S*$/, '')}…`;
  return s;
}

// Link text must not break the Markdown link.
function linkText(text) {
  return oneLine(text, 160).replace(/\[/g, '(').replace(/\]/g, ')');
}

function errorText(error) {
  if (!error) return 'unknown error';
  if (typeof error === 'string') return oneLine(error, 200);
  return oneLine(error.message || error.description || JSON.stringify(error), 200);
}

// Joins a heading and bullet lines, dropping trailing bullets that would
// exceed the Talk message budget.
function buildMessage(head, lines, footer) {
  let out = head;
  let dropped = 0;
  for (const line of lines) {
    if (out.length + line.length + 1 + (footer ? footer.length + 2 : 0) > MAX_MESSAGE) {
      dropped += 1;
      continue;
    }
    out += `\n${line}`;
  }
  if (dropped) out += `\n- …and ${dropped} more`;
  if (footer) out += `\n\n${footer}`;
  return out;
}

// Morning digest template from two Nextcloud MCP calls. No LLM.
const opt = $('Run options').first().json;
const zone = 'Europe/Athens';
const MAX = 2500;

function toolResult(nodeName) {
  const raw = $(nodeName).first().json;
  if (raw.error) throw new Error(`${nodeName}: ${errorText(raw.error)}`);
  const text = String(raw.data ?? '');
  const dataLines = text.split(/\r?\n/).filter((l) => l.startsWith('data:'));
  let rpc;
  try { rpc = JSON.parse(dataLines.length ? dataLines[dataLines.length - 1].slice(5) : text); } catch (e) { rpc = null; }
  if (!rpc) throw new Error(`${nodeName}: unreadable response: ${oneLine(text, 120)}`);
  if (rpc.error) throw new Error(`${nodeName}: ${errorText(rpc.error)}`);
  const result = rpc.result || {};
  let payload = result.structuredContent;
  if (!payload || payload.result !== undefined) {
    try { payload = JSON.parse(result.content?.[0]?.text ?? ''); } catch (e) { payload = null; }
  }
  if (result.isError || !payload || payload.success === false) {
    throw new Error(`${nodeName}: ${oneLine(result.content?.[0]?.text || JSON.stringify(result), 200)}`);
  }
  return payload;
}

const eventsRes = toolResult("Today's events");
const todosRes = toolResult('Open to-dos');

const events = (eventsRes.events || [])
  .filter((e) => String(e.status || '').toUpperCase() !== 'CANCELLED')
  .map((e) => {
    const title = oneLine(e.summary || '(no title)', 120);
    if (e.all_day) return { sort: '', line: `- All day: ${title}` };
    const s = DateTime.fromISO(String(e.start || '')).setZone(zone);
    const en = DateTime.fromISO(String(e.end || '')).setZone(zone);
    if (!s.isValid) return { sort: '', line: `- ${title}` };
    return { sort: s.toFormat('HH:mm'), line: `- ${s.toFormat('HH:mm')}${en.isValid ? `–${en.toFormat('HH:mm')}` : ''} ${title}` };
  })
  .sort((a, b) => a.sort.localeCompare(b.sort));

const dueDate = (t) => {
  const v = t.current_due || t.due;
  if (!v) return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  const d = DateTime.fromISO(String(v)).setZone(zone);
  return d.isValid ? d.toISODate() : null;
};
const lists = {};
for (const t of todosRes.todos || []) {
  const status = String(t.status || '').toUpperCase();
  if (status === 'COMPLETED' || status === 'CANCELLED' || t.completed || Number(t.percent_complete) >= 100) continue;
  const name = oneLine(t.calendar_display_name || t.calendar_name || 'Tasks');
  (lists[name] ||= []).push({
    title: oneLine(t.summary || '(no title)', 100),
    dueDate: dueDate(t),
    priority: Number(t.priority) || 10,
  });
}

const bySoonest = (a, b) => (a.dueDate || '9999').localeCompare(b.dueDate || '9999') || a.priority - b.priority;
const due = [];
const perList = [];
for (const name of Object.keys(lists).sort((a, b) => a.localeCompare(b))) {
  const todos = lists[name].sort(bySoonest);
  for (const t of todos) if (t.dueDate && t.dueDate <= opt.today) due.push({ ...t, list: name });
  const top = todos.slice(0, 3).map((t) => t.title.replace(/;/g, ',')).join('; ');
  perList.push(`- **${linkText(name)}** (${todos.length}): ${top}`);
}
due.sort(bySoonest);
const openCount = Object.values(lists).reduce((n, l) => n + l.length, 0);
const warnings = [...(eventsRes.errors || []), ...(todosRes.errors || [])].map((e) => errorText(e));

let message = '';
if (events.length || openCount) {
  const sections = [`### Good morning, ${opt.weekday} ${opt.today}`];
  if (events.length) sections.push('', '**Today**', ...events.map((e) => e.line));
  if (due.length) {
    sections.push('', '**Due or overdue**', ...due.slice(0, 12).map((t) => `- ${t.title} (${t.list}, ${t.dueDate === opt.today ? 'due today' : `due ${t.dueDate}`})`));
    if (due.length > 12) sections.push(`- …and ${due.length - 12} more`);
  }
  if (perList.length) sections.push('', '**Open per list**', ...perList);
  if (warnings.length) sections.push('', `_Not read: ${warnings.slice(0, 3).join('; ')}_`);
  message = sections.join('\n');
  while (message.length > MAX && sections.length > 2) {
    sections.splice(sections.length - 1, 1);
    message = `${sections.join('\n')}\n- …`;
  }
}
return [{ json: { message, deliver: Boolean(message) && !opt.dry_run, dry_run: opt.dry_run, events: events.length, open_todos: openCount, due: due.length } }];

// Not delivered: a dry run, or nothing to report. Returned to a calling workflow.
const r = $input.first().json;
return [{ json: { ...r, delivered: false, reason: r.message ? 'dry run' : 'nothing to report' } }];

// This workflow is its own error workflow. Only failures of scheduled runs
// are posted; manual runs and dry runs show the error in n8n instead.
const e = $input.first().json;
const execution = e.execution || {};
const mode = String(execution.mode || '');
const node = execution.lastNodeExecuted || execution.error?.node?.name || 'unknown node';
const reason = String(execution.error?.message || execution.error?.description || 'unknown error').replace(/\s+/g, ' ').trim().slice(0, 300);
const message = `**${"morning-digest"} digest failed** (n8n, node "${node}"): ${reason}`;
return [{ json: { message, deliver: mode === 'trigger' || mode === 'webhook', mode } }];
